package com.tenora365.controller;import com.tenora365.entity.*;import com.tenora365.repository.*;import com.tenora365.tenant.TenantContext;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/commercial") public class CommercialController{final SubscriptionRepository subs;final PaymentOrderRepository orders;final SchoolRepository schools;CommercialController(SubscriptionRepository s,PaymentOrderRepository o,SchoolRepository sc){subs=s;orders=o;schools=sc;}@GetMapping("/subscriptions")List<Subscription> subscriptions(){return subs.findBySchoolIdOrderByIdDesc(TenantContext.get());}@PostMapping("/subscriptions")Subscription subscription(@RequestBody Map<String,Object>x){Subscription s=new Subscription();s.setSchool(schools.findById(TenantContext.get()).orElseThrow());s.setPlanCode(String.valueOf(x.getOrDefault("planCode","STARTER")));s.setBillingCycle(String.valueOf(x.getOrDefault("billingCycle","MONTHLY")));s.setAmount(new BigDecimal(String.valueOf(x.getOrDefault("amount","999"))));s.setStatus("PENDING");s.setStartsAt(Instant.now());return subs.save(s);}@PostMapping("/orders")PaymentOrder order(@RequestBody Map<String,Object>x){PaymentOrder o=new PaymentOrder();o.setSchool(schools.findById(TenantContext.get()).orElseThrow());o.setOrderNo("ORD-"+UUID.randomUUID());o.setAmount(new BigDecimal(String.valueOf(x.getOrDefault("amount","999"))));o.setCurrency("INR");o.setStatus("CREATED");o.setProvider(System.getenv().getOrDefault("PAYMENT_PROVIDER","mock"));return orders.save(o);}}
